     1→# =============================================================================
     2→# ntfy Template: PBS Backup
     3→# =============================================================================
     4→# Formats Proxmox Backup Server backup notifications
     5→# Usage: POST to ntfy with ?template=pbs-backup
     6→#
     7→# Expected JSON payload:
     8→# {
     9→#   "status": "success|failure",
    10→#   "container_name": "n8n",
    11→#   "container_id": "502",
    12→#   "namespace": "lxc-containers",
    13→#   "duration": 120,
    14→#   "backup_size": "1.2 GB",
    15→#   "retention": 7,
    16→#   "error_message": "..." (optional, for failures)
    17→# }
    18→# =============================================================================
    19→
    20→# Title template
    21→title: |
    22→  {{- $status := .status -}}
    23→  {{- $name := .container_name -}}
    24→  {{- if eq $status "success" -}}
    25→    💾 Backup Success: {{ $name }}
    26→  {{- else if eq $status "failure" -}}
    27→    🚨 Backup Failed: {{ $name }}
    28→  {{- else -}}
    29→    ⚠️ Backup: {{ $name }}
    30→  {{- end -}}
    31→
    32→# Message template
    33→message: |
    34→  {{- $status := .status -}}
    35→
    36→  Container: {{ .container_name }} (LXC {{ .container_id }})
    37→  Status: {{- if eq $status "success" }} SUCCESS ✓{{- else if eq $status "failure" }} FAILED ✗{{- else }} {{ $status | upper }}{{- end }}
    38→
    39→  {{- if .namespace }}
    40→  Namespace: {{ .namespace }}
    41→  {{- end }}
    42→
    43→  {{- if .duration }}
    44→  Duration: {{ .duration }}s
    45→  {{- end }}
    46→
    47→  {{- if .backup_size }}
    48→  Size: {{ .backup_size }}
    49→  {{- end }}
    50→
    51→  {{- if .retention }}
    52→  Retention: {{ .retention }} backups
    53→  {{- end }}
    54→
    55→  {{- if .error_message }}
