input.content:
# =============================================================================
# Authentik OIDC Integration for Grafana
# =============================================================================
# Configures Grafana to use Authentik as its identity provider via OIDC.
# Users can log in with their Google account through Authentik.
#
# References:
# - https://grafana.com/docs/grafana/latest/setup-grafana/configure-security/configure-authentication/generic-oauth/
# - https://docs.goauthentik.io/integrations/services/grafana/
# =============================================================================

# -----------------------------------------------------------------------------
# OIDC Client Secret
# -----------------------------------------------------------------------------

resource "random_password" "grafana_oidc_secret" {
  length  = 64
  special = false
}

# -----------------------------------------------------------------------------
# Authentik OAuth2/OIDC Provider for Grafana
# -----------------------------------------------------------------------------

data "authentik_certificate_key_pair" "default" {
  name = "authentik Self-signed Certificate"
}

data "authentik_flow" "default_authorization" {
  slug = "default-provider-authorization-implicit-consent"
}

data "authentik_flow" "default_invalidation" {
  slug = "default-provider-invalidation-flow"
}

# Property mappings for OIDC scopes
data "authentik_property_mapping_provider_scope" "openid" {
  managed = "goauthentik.io/providers/oauth2/scope-openid"
}

data "authentik_property_mapping_provider_scope" "email" {
  managed = "goauthentik.io/providers/oauth2/scope-email"
}

data "authentik_property_mapping_provider_scope" "profile" {
  managed = "goauthentik.io/providers/oauth2/scope-profile"
}

resource "authentik_provider_oauth2" "grafana" {
  name               = "Grafana"
  client_id          = "grafana"
  client_secret      = random_password.grafana_oidc_secret.result
  authorization_flow = data.authentik_flow.default_authorization.id
  invalidation_flow  = data.authentik_flow.default_invalidation.id

  # Redirect URIs for Grafana
  allowed_redirect_uris = [
    {
      matching_mode = "strict"
      url           = "https://grafana.${var.domain_internal}/login/generic_oauth"
    },
  ]

  # OIDC property mappings
  property_mappings = [
    data.authentik_property_mapping_provider_scope.openid.id,
    data.authentik_property_mapping_provider_scope.email.id,
    data.authentik_property_mapping_provider_scope.profile.id,
  ]

  # Signing key
  signing_key = data.authentik_certificate_key_pair.default.id
}

# -----------------------------------------------------------------------------
# Authentik Application for Grafana
# -----------------------------------------------------------------------------

resource "authentik_application" "grafana" {
  name              = "Grafana"
  slug              = "grafana"
  protocol_provider = authentik_provider_oauth2.grafana.id

  meta_icon        = "https://grafana.com/static/assets/img/fav32.png"
  meta_description = "Observability dashboards and visualization"
  meta_publisher   = "Homelab"
  meta_launch_url  = "https://grafana.${var.domain_internal}"

  # Open to all authenticated users
  policy_engine_mode = "any"
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------

output "grafana_oidc_issuer_url" {
  description = "OIDC issuer URL for Grafana"
  value       = "https://auth.${var.domain_public}/application/o/grafana/"
}

output "grafana_oidc_client_id" {
  description = "OIDC client ID for Grafana"
  value       = authentik_provider_oauth2.grafana.client_id
}

output "grafana_oidc_client_secret" {
  description = "OIDC client secret for Grafana"
  value       = random_password.grafana_oidc_secret.result
  sensitive   = true
}

